 11	import { useFileTree, flattenFiles, LocalFile } from './useFileTree'
 12	import { useDriveAssignments, resolveEffectiveAssignments, DriveAssignment, PickerTarget } from './useDriveAssignments'
 13	import { useInclusion } from './useInclusion'
 14	import { useSelection } from './useSelection'
 15	import * as uploadQueue from './uploadQueue'
 16	import * as pageCache from '../../lib/pageCache'
 17	import { ellipsisPath } from '../../utils'
 18	import styles from './index.module.css'
 19	
 20	export default function DriveUploadMode() {
 21	  const { root, tree, loading, error, pickRoot } = useFileTree()
 22	  const isEmpty = tree !== null && tree.files.length === 0 && tree.subgroups.length === 0
 23	
 24	  const [selectedFile, setSelectedFile] = useState<LocalFile | null>(null)
 25	  const [selectedPage, setSelectedPage] = useState(1)
 26	  const handleSelectFile = (file: LocalFile) => {
 27	    setSelectedFile(file)
 28	    setSelectedPage(1)
 29	  }
 30	
 31	  useEffect(() => {
 32	    return () => { if (selectedFile) pageCache.evict(selectedFile.path) }
 33	    // eslint-disable-next-line react-hooks/exhaustive-deps
 34	  }, [selectedFile?.path])
 35	
 36	  // Groups start expanded; presence in this set (keyed by the group's full
 37	  // path, e.g. "invoices/2026") means collapsed.
 38	  const [collapsedGroups, setCollapsedGroups] = useState<Set<string>>(new Set())
 39	  const toggleGroup = (groupKey: string) => {
 40	    setCollapsedGroups(prev => {
 41	      const next = new Set(prev)
 42	      if (next.has(groupKey)) next.delete(groupKey); else next.add(groupKey)
 43	      return next
 44	    })
 45	  }
 46	
 47	  const inclusion = useInclusion(tree)
 48	  const selection = useSelection(tree)
 49	  const assignments = useDriveAssignments()
 50	  const [pickerTarget, setPickerTarget] = useState<PickerTarget | null>(null)
 51	  const handlePicked = (folder: DriveAssignment) => {
 52	    if (pickerTarget?.type === 'group') assignments.setGroupAssignment(pickerTarget.key, folder)
 53	    else if (pickerTarget?.type === 'file') assignments.setFileOverride(pickerTarget.path, folder)
 54	    setPickerTarget(null)
 55	  }
 56	
 57	  const [uploadModalOpen, setUploadModalOpen] = useState(false)
 58	  // Once Upload All is clicked, the tree locks for the rest of this tree's
 59	  // session — the upload starts immediately, so there's no "in progress but
 60	  // not locked yet" window to account for. Retrying failed files happens
 61	  // inside the upload modal, not from here, so this never needs to go back
 62	  // to false except via a fresh root pick.
 63	  const [started, setStarted] = useState(false)
 64	  const allFiles = tree ? flattenFiles(tree) : []
 65	  const selectedFiles = allFiles.filter(f => inclusion.isFileSelected(f.path))
 66	  const effectiveAssignments = tree ? resolveEffectiveAssignments(tree, assignments) : null
 67	  const readyToUpload = selectedFiles.length > 0 && selectedFiles.every(f => effectiveAssignments!.get(f.path) != null)
 68	
 69	  const handleUploadAll = () => {
 70	    if (!tree || !effectiveAssignments) return
 71	    uploadQueue.start(selectedFiles.map(f => {
 72	      const assignment = effectiveAssignments.get(f.path)
 73	      // Upload All is disabled until readyToUpload is true, so every file
 74	      // should resolve here — this is a defensive check against that
 75	      // guard and this walk drifting out of sync, not an expected path.
 76	      if (!assignment) throw new Error(`No Drive folder assigned for "${f.path}"`)
 77	      return { path: f.path, folderId: assignment.driveFolderId, name: f.name }
 78	    }))
 79	    setStarted(true)
 80	    setUploadModalOpen(true)
 81	  }
 82	  const handlePickRoot = async () => {
 83	    // A new root discards the old tree's upload-queue state along with it —
 84	    // picking a new root is the only way out of the read-only lock.
 85	    if (await pickRoot()) {
 86	      uploadQueue.reset()
 87	      setStarted(false)
 88	    }
 89	  }
 90	
 91	  return (
 92	    <Box className={styles.root}>
 93	      <Toolbar>
 94	        <Button size="xs" variant="default" onClick={handlePickRoot}>
 95	          {root ? ellipsisPath(root) : 'Choose root folder…'}
 96	        </Button>
 97	        <Box className={styles.toolbarSpacer} />
 98	        <Button size="xs" variant="default" disabled={started || !tree} onClick={inclusion.selectAll}>
 99	          Select All
100	        </Button>
101	        <Button size="xs" variant="default" disabled={started || !tree} onClick={inclusion.selectNone}>
102	          Select None
103	        </Button>
104	        <Tooltip
105	          label={tree ? 'Every selected file needs a Drive folder before uploading' : 'Choose a root folder first'}
106	          disabled={started || readyToUpload}
107	        >
108	          <span>
109	            <Button size="xs" disabled={started || !readyToUpload} onClick={handleUploadAll}>
110	              Upload All
111	            </Button>
112	          </span>
113	        </Tooltip>
114	      </Toolbar>
115	
116	      <Box className={styles.body}>
117	        <ResizableLeftPanel
118	          left={
119	            <>
120	              <DriveFolderPickerModal
121	                opened={pickerTarget !== null}
122	                onClose={() => setPickerTarget(null)}
123	                onSelect={handlePicked}
124	              />
125	              {tree && (
126	                <UploadModal
127	                  opened={uploadModalOpen}
128	                  tree={tree}
129	                  onClose={() => setUploadModalOpen(false)}
130	                />
131	              )}
132	
133	              {loading && <Loader size="sm" />}
134	              {error && <Text size="sm" c="red">{error}</Text>}
135	              {!loading && !error && isEmpty && (
136	                <Text size="sm" c="dimmed">No files found under this folder.</Text>
137	              )}
138	
139	              {tree && (
140	                <Stack gap="md">
141	                  {tree.subgroups.map(group => (
142	                    <GroupNode
143	                      key={group.name}
144	                      group={group}
145	                      groupKey={group.name}
146	                      collapsedGroups={collapsedGroups}
147	                      onToggle={toggleGroup}
148	                      assignments={assignments}
149	                      inheritedAssignment={null}
150	                      inclusion={inclusion}
151	                      selection={selection}
152	                      locked={started}
153	                      onPick={setPickerTarget}
154	                      onSelectFile={handleSelectFile}
155	                    />
156	                  ))}
157	                  <FileList
158	                    files={tree.files}
159	                    assignments={assignments}
160	                    inheritedAssignment={null}
161	                    inclusion={inclusion}
162	                    selection={selection}
163	                    locked={started}
164	                    onPick={setPickerTarget}
165	                    onSelectFile={handleSelectFile}
166	                  />
167	                </Stack>
168	              )}
169	            </>
170	          }
171	        >
172	          <DriveThumbnailPanel
173	            pdfPath={selectedFile?.path ?? null}
174	            pageCount={selectedFile?.pageCount ?? 0}
175	            selectedPage={selectedPage}
176	            onSelectPage={setSelectedPage}
177	          />
178	
179	          {selectedFile
180	            ? <DetailPanel pdfPath={selectedFile.path} pageNum={selectedPage} pageCount={selectedFile.pageCount} />
181	            : <Box className={styles.emptyDetail} />}
182	        </ResizableLeftPanel>
183	      </Box>
184	    </Box>
185	  )
186	}

