 29	export default function GroupNode({ group, groupKey, collapsedGroups, onToggle, assignments, inheritedAssignment, inclusion, selection, locked, onPick, onSelectFile }: Props) {
 30	  const expanded = !collapsedGroups.has(groupKey)
 31	  const own = assignments.groupAssignments.get(groupKey) ?? null
 32	  const effective = own ?? inheritedAssignment
