 95	            inclusion={inclusion}
 96	            selection={selection}
 97	            locked={locked}
 98	            onPick={onPick}
 99	            onSelectFile={onSelectFile}
100	          />
101	          {group.subgroups.length > 0 && (
102	            <Stack gap={8} mt={4}>
103	              {group.subgroups.map(sub => (
104	                <GroupNode
105	                  key={sub.name}
106	                  group={sub}
107	                  groupKey={`${groupKey}/${sub.name}`}
108	                  collapsedGroups={collapsedGroups}
109	                  onToggle={onToggle}
110	                  assignments={assignments}
111	                  inheritedAssignment={effective}
112	                  inclusion={inclusion}
113	                  selection={selection}
114	                  locked={locked}
115	                  onPick={onPick}
116	                  onSelectFile={onSelectFile}
117	                />
118	              ))}
119	            </Stack>
120	          )}
121	        </Box>
122	      )}
123	    </Box>
124	  )
125	}

