 1	import { Badge, Box, Checkbox, Group, Stack, Text, Tooltip } from '@mantine/core'
 2	import DriveAssignmentField from './DriveAssignmentField'
 3	import TruncatedText from '../TruncatedText'
 4	import { LocalFile } from './useFileTree'
 5	import { DriveAssignment, DriveAssignmentsHandle, PickerTarget } from './useDriveAssignments'
 6	import { InclusionHandle } from './useInclusion'
 7	import { SelectionHandle } from './useSelection'
 8	import { OpenDriveFolder } from '../../../wailsjs/go/main/App'
 9	import { handlePromiseRejection } from '../../lib/globalErrorHandler'
10	import { formatFileSize } from '../../utils'
11	import styles from './FileList.module.css'
12	
13	interface Props {
14	  files: LocalFile[]
15	  assignments: DriveAssignmentsHandle
16	  inheritedAssignment: DriveAssignment | null
17	  inclusion: InclusionHandle
18	  selection: SelectionHandle
19	  locked: boolean
20	  onPick: (target: PickerTarget) => void
21	  onSelectFile: (file: LocalFile) => void
22	}
23	
24	export default function FileList({ files, assignments, inheritedAssignment, inclusion, selection, locked, onPick, onSelectFile }: Props) {
25	  return (
26	    <Stack gap={10} mt={4}>
27	      {files.map(file => {
28	        const own = assignments.fileOverrides.get(file.path) ?? null
29	        const effective = own ?? inheritedAssignment
30	        const previewable = file.isPdf && !file.corrupt
31	        const detail = [
32	          file.corrupt ? 'Unreadable' : file.isPdf ? `${file.pageCount} pages` : null,
33	          formatFileSize(file.sizeBytes),
34	        ].filter(Boolean).join(' · ')
35	        const handleRowClick = (e: React.MouseEvent) => {
36	          const item = { type: 'file' as const, path: file.path }
37	          if (e.metaKey || e.ctrlKey) selection.toggle(item); else selection.replace(item)
38	          if (previewable) onSelectFile(file)
39	        }
40	        return (
41	          <Box
42	            key={file.path}
43	            pl={4}
44	            py={2}
45	            onClick={handleRowClick}
46	            aria-selected={selection.isSelected({ type: 'file', path: file.path })}
47	            className={`${styles.row} ${styles.rowClickable} ${selection.isSelected({ type: 'file', path: file.path }) ? styles.rowSelected : ''}`}
48	          >
49	            <Group gap={8} wrap="nowrap" align="center">
50	              <Checkbox
51	                size="xs"
52	                checked={inclusion.isFileSelected(file.path)}
53	                disabled={locked}
54	                onClick={e => e.stopPropagation()}
55	                onChange={() => inclusion.toggleFile(file.path)}
56	                aria-label={`Include ${file.name} in upload`}
57	              />
58	              <Group gap={4} wrap="nowrap" className={styles.nameGroup}>
59	                {file.isPdf && (
60	                  <Badge size="xs" variant="light" color="red" radius="sm" className={styles.pdfBadge}>
61	                    PDF
62	                  </Badge>
63	                )}
64	                <TruncatedText label={file.name} size="sm" c={file.corrupt ? 'red' : undefined}>
65	                  {file.isPdf ? '' : '📄 '}{file.name}
66	                </TruncatedText>
67	                {file.corrupt && (
68	                  <Tooltip label="Could not read this file — it may be corrupt or not a valid PDF">
69	                    <span>⚠️</span>
70	                  </Tooltip>
71	                )}
72	              </Group>
73	              <Box onClick={e => e.stopPropagation()}>
74	                <DriveAssignmentField
75	                  label={file.name}
76	                  assignment={effective}
77	                  isOwn={own !== null}
78	                  locked={locked}
79	                  onPick={() => onPick({ type: 'file', path: file.path })}
80	                  onClear={() => assignments.clearFileOverride(file.path)}
81	                  onOpen={() => effective && OpenDriveFolder(effective.driveFolderId).catch(handlePromiseRejection('Opening Drive folder failed'))}
82	                />
83	              </Box>
84	            </Group>
85	            <Text size="xs" c="dimmed" mt={2}>
86	              {detail}
87	            </Text>
88	          </Box>
89	        )
90	      })}
91	    </Stack>
92	  )
93	}

