 11	import UploadModal from './UploadModal'
 12	import { useFileTree, flattenFiles, LocalFile } from './useFileTree'
 13	import { useDriveAssignments, resolveEffectiveAssignments, DriveAssignment, PickerTarget } from './useDriveAssignments'
 14	import { useInclusion } from './useInclusion'
 15	import { useSelection } from './useSelection'
 16	import * as uploadQueue from './uploadQueue'
 17	import * as pageCache from '../../lib/pageCache'
 18	import { ellipsisPath } from '../../utils'
 19	import styles from './index.module.css'
 20	
 21	export default function DriveUploadMode() {
 22	  const { root, tree, loading, error, pickRoot } = useFileTree()
 23	  const isEmpty = tree !== null && tree.files.length === 0 && tree.subgroups.length === 0
 24	
 25	  // The last previewable file touched by a click — independent of the
 26	  // multi-selection (see useSelection): any click on a previewable file
 27	  // updates this, whether it's adding or removing that file from the
 28	  // selection, while clicking a subfolder or a non-previewable file leaves
 29	  // it as whatever was last previewed.
 30	  const [previewedFile, setPreviewedFile] = useState<LocalFile | null>(null)
 31	  const [previewedPage, setPreviewedPage] = useState(1)
 32	  const handlePreviewFile = (file: LocalFile) => {
 33	    setPreviewedFile(file)
 34	    setPreviewedPage(1)
 35	  }
 36	
 37	  useEffect(() => {
 38	    return () => { if (previewedFile) pageCache.evict(previewedFile.path) }
 39	    // eslint-disable-next-line react-hooks/exhaustive-deps
 40	  }, [previewedFile?.path])
 41	
 42	  // Groups start expanded; presence in this set (keyed by the group's full
 43	  // path, e.g. "invoices/2026") means collapsed.
 44	  const [collapsedGroups, setCollapsedGroups] = useState<Set<string>>(new Set())
 45	  const toggleGroup = (groupKey: string) => {
 46	    setCollapsedGroups(prev => {
 47	      const next = new Set(prev)
 48	      if (next.has(groupKey)) next.delete(groupKey); else next.add(groupKey)
 49	      return next
 50	    })
 51	  }
 52	
 53	  const inclusion = useInclusion(tree)
 54	  const selection = useSelection(tree)
 55	  const assignments = useDriveAssignments()
 56	  const [pickerTarget, setPickerTarget] = useState<PickerTarget | null>(null)
 57	  const handlePicked = (folder: DriveAssignment) => {
 58	    if (pickerTarget?.type === 'group') assignments.setGroupAssignment(pickerTarget.key, folder)
 59	    else if (pickerTarget?.type === 'file') assignments.setFileOverride(pickerTarget.path, folder)
 60	    setPickerTarget(null)
 61	  }
 62	
 63	  const [uploadModalOpen, setUploadModalOpen] = useState(false)
 64	  // Once Upload All is clicked, the tree locks for the rest of this tree's
 65	  // session — the upload starts immediately, so there's no "in progress but
 66	  // not locked yet" window to account for. Retrying failed files happens
 67	  // inside the upload modal, not from here, so this never needs to go back
 68	  // to false except via a fresh root pick.
 69	  const [started, setStarted] = useState(false)
 70	  const allFiles = tree ? flattenFiles(tree) : []
 71	  const selectedFiles = allFiles.filter(f => inclusion.isFileSelected(f.path))
 72	  const effectiveAssignments = tree ? resolveEffectiveAssignments(tree, assignments) : null
 73	  const readyToUpload = selectedFiles.length > 0 && selectedFiles.every(f => effectiveAssignments!.get(f.path) != null)
 74	
 75	  const handleUploadAll = () => {
 76	    if (!tree || !effectiveAssignments) return
 77	    uploadQueue.start(selectedFiles.map(f => {
 78	      const assignment = effectiveAssignments.get(f.path)
 79	      // Upload All is disabled until readyToUpload is true, so every file
 80	      // should resolve here — this is a defensive check against that
 81	      // guard and this walk drifting out of sync, not an expected path.
 82	      if (!assignment) throw new Error(`No Drive folder assigned for "${f.path}"`)
 83	      return { path: f.path, folderId: assignment.driveFolderId, name: f.name }
 84	    }))
 85	    setStarted(true)
 86	    setUploadModalOpen(true)
 87	  }
 88	  const handlePickRoot = async () => {
 89	    // A new root discards the old tree's upload-queue state along with it —
 90	    // picking a new root is the only way out of the read-only lock.
 91	    if (await pickRoot()) {
 92	      uploadQueue.reset()
 93	      setStarted(false)
 94	    }
 95	  }
 96	
 97	  return (
 98	    <Box className={styles.root}>
 99	      <Toolbar>
100	        <Button size="xs" variant="default" onClick={handlePickRoot}>
101	          {root ? ellipsisPath(root) : 'Choose root folder…'}
102	        </Button>
103	        <Box className={styles.toolbarSpacer} />
104	        <Button size="xs" variant="default" disabled={started || !tree} onClick={inclusion.selectAll}>
105	          Select All
106	        </Button>
107	        <Button size="xs" variant="default" disabled={started || !tree} onClick={inclusion.selectNone}>
108	          Select None
109	        </Button>
110	        <Tooltip
111	          label={tree ? 'Every selected file needs a Drive folder before uploading' : 'Choose a root folder first'}
112	          disabled={started || readyToUpload}
113	        >
114	          <span>
115	            <Button size="xs" disabled={started || !readyToUpload} onClick={handleUploadAll}>
116	              Upload All
117	            </Button>
118	          </span>
119	        </Tooltip>
120	      </Toolbar>
121	
122	      <Box className={styles.body}>
123	        <ResizableLeftPanel
124	          left={
125	            <>
126	              <DriveFolderPickerModal
127	                opened={pickerTarget !== null}
128	                onClose={() => setPickerTarget(null)}
129	                onSelect={handlePicked}
130	              />
131	              {tree && (
132	                <UploadModal
133	                  opened={uploadModalOpen}
134	                  tree={tree}
135	                  onClose={() => setUploadModalOpen(false)}
136	                />
137	              )}
138	
139	              {loading && <Loader size="sm" />}
140	              {error && <Text size="sm" c="red">{error}</Text>}
141	              {!loading && !error && isEmpty && (
142	                <Text size="sm" c="dimmed">No files found under this folder.</Text>
143	              )}
144	
145	              {tree && (
146	                <Stack gap="md">
147	                  {tree.subgroups.map(group => (
148	                    <GroupNode
149	                      key={group.name}
150	                      group={group}
151	                      groupKey={group.name}
152	                      collapsedGroups={collapsedGroups}
153	                      onToggle={toggleGroup}
154	                      assignments={assignments}
155	                      inheritedAssignment={null}
156	                      inclusion={inclusion}
157	                      selection={selection}
158	                      locked={started}
159	                      onPick={setPickerTarget}
160	                      onPreviewFile={handlePreviewFile}
161	                    />
162	                  ))}
163	                  <FileList
164	                    files={tree.files}
165	                    assignments={assignments}
166	                    inheritedAssignment={null}
167	                    inclusion={inclusion}
168	                    selection={selection}
169	                    locked={started}
170	                    onPick={setPickerTarget}
171	                    onPreviewFile={handlePreviewFile}
172	                  />
173	                </Stack>
174	              )}
175	            </>
176	          }
177	        >
178	          <DriveThumbnailPanel
179	            pdfPath={previewedFile?.path ?? null}
180	            pageCount={previewedFile?.pageCount ?? 0}
181	            selectedPage={previewedPage}
182	            onSelectPage={setPreviewedPage}
183	          />
184	
185	          <Box className={styles.detailColumn}>
186	            {previewedFile && (
187	              <TruncatedText label={previewedFile.name} size="sm" fw={600} className={styles.detailHeading}>
188	                {previewedFile.name}
189	              </TruncatedText>
190	            )}
191	            {previewedFile
192	              ? <DetailPanel pdfPath={previewedFile.path} pageNum={previewedPage} pageCount={previewedFile.pageCount} />
193	              : <Box className={styles.emptyDetail} />}
194	          </Box>
195	        </ResizableLeftPanel>
196	      </Box>
197	    </Box>
198	  )
199	}

